const config={title:'瀏覽器自動化',subtitle:'AUTOMATION DEMO',first:'scenarios',groups:[{id:'manage',name:'場景管理',en:'SCENARIOS',pages:[{id:'scenarios',name:'自動化場景',desc:'以穩定編號管理腳本、參數、縮圖與執行紀錄。此頁為離線互動原型。'}]},{id:'produce',name:'場景生產',en:'PRODUCTION',pages:[{id:'recording',name:'自主腳本錄製',desc:'草稿 → 標準化 → 驗證 → 發布；以對話調試完善初版腳本。'},{id:'reports',name:'自主交付報告',desc:'依分類、場景多選篩選；保留入參、出參、步驟與失敗證據。'},{id:'playground',name:'自由試驗場',desc:'將已發布場景串成可重現的序列，前一節點的出參可供下一節點使用。'}]},{id:'guide',name:'建置指引',en:'BUILD GUIDE',pages:[{id:'architecture',name:'系統與分工',desc:'功能邊界、模組責任與逐步建置順序。'},{id:'contracts',name:'資料與介面契約',desc:'穩定編號、獨立斷言、版本快照與參數檔。'},{id:'start',name:'執行與驗收',desc:'區分離線原型、真實 Python 範例與新工程待建能力。'}]}]};
const json=v=>JSON.stringify(v,null,2),clone=v=>JSON.parse(JSON.stringify(v));
const badge=(t,c='blue')=>`<span class="badge ${c}">${esc(t)}</span>`;
const inputSchema={type:'object',required:['title','quantity'],additionalProperties:false,properties:{title:{type:'string',minLength:1,maxLength:60},quantity:{type:'integer',minimum:1,maximum:30}}};
const querySchema={type:'object',required:['recordId'],additionalProperties:false,properties:{recordId:{type:'string',minLength:1}}};
const outputSchema={type:'object',required:['recordId','title','quantity'],additionalProperties:false,properties:{recordId:{type:'string',minLength:1},title:{type:'string',minLength:1},quantity:{type:'integer',minimum:1,maximum:30}}};
const seeds=[{id:'BA-001',name:'建立範例紀錄',group:'範例資料',revision:1,state:'已發布',url:'http://127.0.0.1:8765/',inputSchema,defaults:{title:'介面驗證範例',quantity:12},outputSchema,example:{recordId:'DEMO-001',title:'介面驗證範例',quantity:12}},{id:'BA-002',name:'驗證範例紀錄',group:'範例資料',revision:1,state:'已發布',url:'http://127.0.0.1:8765/?view=query',inputSchema:querySchema,defaults:{recordId:'DEMO-001'},outputSchema,example:{recordId:'DEMO-001',title:'介面驗證範例',quantity:12}}];
let state=storeRead('automation-demo-v1',{scenes:clone(seeds),reports:[],flow:['BA-001','BA-002'],draft:null});let selectedNode=0,liveRun=false;
function save(){storeWrite('automation-demo-v1',state)}
const getScene=id=>state.scenes.find(s=>s.id===id);
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-header"><h2>${title}</h2>${extra}</div>${body}</section>`;
function validate(value,schema){if(schema.type!=='object'||!schema.properties||Array.isArray(value)||!value||typeof value!=='object')throw Error('需要 object Schema 與 JSON 物件');for(const k of schema.required||[])if(value[k]===undefined)throw Error('缺少必要參數：'+k);for(const [k,v]of Object.entries(value)){const s=schema.properties[k];if(!s){if(schema.additionalProperties===false)throw Error('不支援的參數：'+k);continue}if(s.type==='integer'&&!Number.isInteger(v)||s.type==='string'&&typeof v!=='string')throw Error(k+' 的型別不符');if(typeof v==='string'&&((s.minLength&&v.trim().length<s.minLength)||(s.maxLength&&v.length>s.maxLength)))throw Error(k+' 的長度不符');if(typeof v==='number'&&((s.minimum!==undefined&&v<s.minimum)||(s.maximum!==undefined&&v>s.maximum)))throw Error(k+' 超出允許範圍')}return value}
function assertLocalUrl(raw){const u=new URL(raw);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('請輸入不含帳密的 HTTP(S) 網址');return u.href}
function scriptSample(s,kind){if(kind==='automation'&&s.code)return s.code;if(kind==='assertion')return `# 獨立斷言示意；完整可執行版本見 python-demo/scenes/assertion.py\nimport json\nfrom pathlib import Path\n\ndef verify(input_path, facts_path):\n    params = json.loads(Path(input_path).read_text())\n    facts = json.loads(Path(facts_path).read_text())\n    assert facts["recordId"].startswith("DEMO-")\n    assert facts["status"] == "已建立"\n    ${s.id==='BA-002'?'assert facts["recordId"] == params["recordId"]':'assert facts["title"] == params["title"]\n    assert facts["quantity"] == params["quantity"]'}\n    return {key: facts[key] for key in ("recordId", "title", "quantity")}\n`;
return `# Python / Playwright 腳本契約示意\n# 完整可執行版本見 python-demo/scenes/automation.py\n# 輸入與輸出一律使用檔案，不把業務參數寫死於腳本。\nimport json\nfrom pathlib import Path\n\ndef automate(page, target_url, input_path):\n    params = json.loads(Path(input_path).read_text())\n    page.goto(target_url, wait_until="domcontentloaded")\n    ${s.id==='BA-002'?'page.get_by_label("紀錄編號").fill(params["recordId"])\n    page.get_by_role("button", name="查詢").click()':'page.get_by_label("標題").fill(params["title"])\n    page.get_by_label("數量").fill(str(params["quantity"]))\n    page.get_by_role("button", name="建立紀錄").click()'}\n    page.locator("#record-id").wait_for(state="visible", timeout=15000)\n    # 擷取 DOM 值至 facts.json，交給獨立斷言。\n`}
function sceneCards(){const q=$('#search')?.value.toLowerCase()||'',group=$('#scene-group')?.value||'';const scenes=state.scenes.filter(s=>(s.id+s.name).toLowerCase().includes(q)&&(!group||s.group===group));$('#cards').innerHTML=scenes.map(s=>`<article class="panel panel-body"><div class="card-meta"><span class="tag">${s.id}</span>${badge(s.state,s.state==='已發布'?'green':'amber')}<span class="muted">v${s.revision}</span></div><h2>${esc(s.name)}</h2><div class="card-meta"><div class="thumb" aria-label="中性示意縮圖"><b></b><i></i><i></i></div><div><strong>${esc(s.group)}</strong><span class="cell-sub">Python 自動化 + 獨立斷言<br>JSON 入參 / 出參 · HTML 報告</span></div></div><div class="card-links"><button class="text-btn" data-action="automation" data-id="${s.id}">自動化腳本</button><button class="text-btn" data-action="assertion" data-id="${s.id}">斷言腳本</button><button class="text-btn" data-action="inputs" data-id="${s.id}">入參設定</button><button class="text-btn" data-action="outputs" data-id="${s.id}">出參設定</button><button class="text-btn" data-action="report" data-id="${s.id}">執行報告</button></div><div class="card-footer"><button class="button" data-action="debug" data-id="${s.id}">調試</button><button class="button primary" data-action="run" data-id="${s.id}" ${s.state!=='已發布'?'disabled':''}>模擬執行</button></div></article>`).join('')||'<div class="empty">沒有相符場景。</div>';
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>sceneAction(b.dataset.action,b.dataset.id))}
function sceneAction(action,id){const s=getScene(id);if(action==='automation'||action==='assertion'){modal(s.id+' · '+(action==='automation'?'自動化腳本':'斷言腳本'),'<div class="notice">下方是契約示意。真實可執行程式位於隨附的 python-demo。</div><pre class="source">'+esc(scriptSample(s,action))+'</pre>',{label:'下載示意腳本',run:()=>download(id+'-'+action+'.py',scriptSample(s,action),'text/x-python')});return}
if(action==='inputs'||action==='outputs'){const input=action==='inputs';modal(id+' · '+(input?'入參設定':'出參設定'),`<div class="notice">修改後建立新版本，須回到錄製頁重新驗證與發布。HTML 僅檢查此範例使用的基本型別；正式後端使用完整 JSON Schema 驗證。</div><label>JSON Schema<textarea id="schema" rows="10" class="code-editor">${esc(json(input?s.inputSchema:s.outputSchema))}</textarea></label><label>${input?'預設值':'樣例值'}<textarea id="values" rows="5" class="code-editor">${esc(json(input?s.defaults:s.example))}</textarea></label><p id="param-error" role="alert"></p>`,{label:'儲存新版本',run:()=>{try{const schema=JSON.parse($('#schema').value),values=JSON.parse($('#values').value);validate(values,schema);if(input){s.inputSchema=schema;s.defaults=values}else{s.outputSchema=schema;s.example=values}s.revision++;s.state='草稿';save();$('#dialog').close();render();toast('已儲存；請先重新驗證並發布')}catch(e){$('#param-error').textContent=e.message}}});return}
if(action==='report'){location.hash='reports';setTimeout(()=>{[...$('#report-scenes').options].forEach(o=>o.selected=o.value===id);reportRows()},0);return}
if(action==='debug'){modal(id+' · 連結與調試上下文',`<label>預設調試網址<input id="debug-url" type="url" value="${esc(s.url)}"></label><div class="notice warn">離線原型不連線瀏覽器或 AI。儲存後可檢視將傳給助手的上下文；真實連線由新工程的瀏覽器工作階段服務實作。</div><div id="debug-context"></div>`,{label:'儲存網址並組裝上下文',run:()=>{try{s.url=assertLocalUrl($('#debug-url').value);save();$('#debug-context').innerHTML='<pre class="source">'+esc(json({sceneId:s.id,revision:s.revision,targetUrl:s.url,inputSchema:s.inputSchema,defaults:s.defaults,outputSchema:s.outputSchema,referenceScene:'BA-001',files:['automation.py','assertion.py'],toolScope:['讀取草稿','觀察獨立瀏覽器','修改草稿','執行候選版本','讀取報告'],rules:['不讀取其他工作階段','不回傳憑證','修改後重新驗證','發布需使用者確認']}))+'</pre>'}catch(e){toast(e.message)}}});return}
if(action==='run')modal(id+' · 模擬執行',`<div class="notice">只在目前頁面產生模擬結果，不呼叫瀏覽器。</div><label>本次入參<textarea id="run-params" rows="7" class="code-editor">${esc(json(s.defaults))}</textarea></label><label><input id="force-fail" type="checkbox"> 模擬斷言失敗</label><p id="run-error" role="alert"></p>`,{label:'檢查並模擬執行',run:()=>{try{const params=validate(JSON.parse($('#run-params').value),s.inputSchema);const fail=$('#force-fail').checked;const r=simulate(s,params,fail);$('#dialog').close();toast(r.status==='passed'?'模擬成功；報告已產生':'模擬失敗；出參未發布');location.hash='reports';if(location.hash==='#reports')render()}catch(e){$('#run-error').textContent=e.message}}})}
function simulate(s,input,fail=false){validate(input,s.inputSchema);let result,error=fail?'示範：畫面值與預期值不同。':null;
if(s.id==='BA-002'){const found=state.reports.find(r=>r.status==='passed'&&r.output?.recordId===input.recordId);result=found?clone(found.output):input.recordId==='DEMO-001'?clone(seeds[1].example):null;if(!result){fail=true;error='示範：查無此紀錄。'}}else result={recordId:'DEMO-'+Date.now().toString(36).toUpperCase(),title:input.title,quantity:input.quantity};
if(!fail){try{validate(result,s.outputSchema)}catch(e){fail=true;error='出參 Schema 不符：'+e.message}}
const r={runId:'SIM-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),sceneId:s.id,sceneName:s.name,group:s.group,revision:s.revision,mode:'離線模擬',status:fail?'failed':'passed',startedAt:new Date().toISOString(),input:clone(input),output:fail?null:result,steps:[{name:'檢查入參',status:'passed'},{name:'模擬瀏覽器步驟',status:'passed'},{name:'獨立斷言與出參檢查',status:fail?'failed':'passed'},{name:'發布出參',status:fail?'skipped':'passed'}],error,artifacts:{screenshot:'離線模式不產生真實截圖',input:'input.json',output:fail?null:'output.json'},scriptSnapshot:scriptSample(s,'automation')};state.reports.unshift(r);save();return r}
function reportHtml(r){return `<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>${esc(r.runId)}</title><style>body{font:14px/1.6 system-ui;color:#24334a;max-width:1000px;margin:24px auto;padding:20px}pre{background:#f5f7fb;padding:16px;white-space:pre-wrap}table{border-collapse:collapse;width:100%}td,th{border:1px solid #e9edf3;padding:8px;text-align:left}.notice{padding:12px;background:#fff5db}</style><h1>${esc(r.sceneId)} 執行報告</h1><p class="notice">離線模擬報告，並未執行真實瀏覽器。此標示不可移除。</p><p>${esc(r.runId)} · v${r.revision} · ${r.status==='passed'?'通過':'失敗'} · ${esc(r.startedAt)}</p><h2>入參</h2><pre>${esc(json(r.input))}</pre><h2>出參</h2><pre>${esc(json(r.output))}</pre><h2>步驟</h2><table>${r.steps.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.status)}</td></tr>`).join('')}</table><h2>診斷</h2><p>${esc(r.error||'無模擬異常')}</p><p>${esc(r.artifacts.screenshot)}</p><h2>腳本快照</h2><pre>${esc(r.scriptSnapshot)}</pre></html>`}
function reportRows(){const ids=[...$('#report-scenes').selectedOptions].map(o=>o.value),groups=[...$('#report-groups').selectedOptions].map(o=>o.value);const status=$('#report-status').value;const rows=state.reports.filter(r=>(!ids.length||ids.includes(r.sceneId))&&(!groups.length||groups.includes(r.group))&&(!status||r.status===status));$('#report-table').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr><th>執行編號 / 時間</th><th>場景</th><th>版本</th><th>模式</th><th>結果</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="tag">${r.runId}</span><span class="cell-sub">${esc(new Date(r.startedAt).toLocaleString('zh-TW'))}</span></td><td>${esc(r.sceneId+' '+r.sceneName)}</td><td>v${r.revision}</td><td>離線模擬</td><td>${badge(r.status==='passed'?'通過':'失敗',r.status==='passed'?'green':'red')}</td><td><button class="text-btn" data-report="${r.runId}">檢視報告</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚無相符報告。請到場景管理執行一次模擬。</div>';document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{const r=state.reports.find(x=>x.runId===b.dataset.report);modal(r.sceneId+' · '+r.runId,`<div class="notice">${r.mode} · ${r.status==='passed'?'通過':'失敗'} · v${r.revision}</div><h3>入參 / 出參</h3><div class="field-pair"><pre class="source">${esc(json(r.input))}</pre><pre class="source">${esc(json(r.output))}</pre></div><h3>階段記錄</h3><ul>${r.steps.map(s=>`<li>${esc(s.name)}：${esc(s.status)}</li>`).join('')}</ul><p>${esc(r.error||'無模擬異常')}</p><p class="muted">沒有真實瀏覽器截圖；真實執行範例會產生 screenshot.png。</p>`,{label:'下載 HTML 報告',run:()=>download(r.runId+'.html',reportHtml(r),'text/html')})})}
function recordingBody(){const d=state.draft;return `<div class="notice warn">此處演示生產流程，不錄製真實瀏覽器，也不呼叫 AI。真實錄製命令與可執行腳本見「執行與驗收」。</div><div class="stepbar">${['1 錄製草稿','2 調試與標準化','3 驗證候選版','4 確認發布'].map((x,i)=>`<span class="${d&&((d.validated&&i===3)||(!d.validated&&i===1))?'active':''}">${x}</span>`).join('')}</div><div class="two-col">${panel('錄製設定',`<div class="panel-body stack"><label>目標場景<select id="record-scene">${state.scenes.map(s=>`<option value="${s.id}" ${d?.sceneId===s.id?'selected':''}>${s.id} · ${esc(s.name)}</option>`).join('')}</select></label><label>目標網址<input id="record-url" value="${esc(d?.url||state.scenes[0].url)}"></label><button class="button primary" id="record-start">產生示範錄製草稿</button><p class="muted">真實實作：建立隔離瀏覽器 → 使用者操作 → 停止錄製 → 儲存不可變原稿。</p><h3>對話調試上下文</h3><ul class="muted"><li>目標網址、角色、步驟與成功條件</li><li>目前草稿、Schema、最近錯誤與截圖</li><li>BA-001 標準範例與檔案契約</li><li>僅限本工作階段的觀察、修改、執行工具</li></ul></div>`)}${panel('候選版本',`<div class="panel-body stack">${d?`<p><span class="tag">${d.sceneId}</span> 候選 v${d.revision} ${badge(d.validated?'範例檢查通過':'待驗證',d.validated?'green':'amber')}</p><label>草稿內容<textarea id="draft-code" class="code-editor" rows="14">${esc(d.code)}</textarea></label><div class="actions"><button class="button" id="draft-save">儲存修改</button><button class="button" id="draft-validate">檢查示範契約</button><button class="button primary" id="draft-publish" ${!d.validated?'disabled':''}>確認發布</button></div><p class="muted">原型只檢查草稿是否包含 automate、params 及頁面觀察；不代表 Python 語法或實際步驟通過。正式發布必須使用同版真實執行結果。</p>`:'<div class="empty">先產生一份示範錄製草稿。</div>'}</div>`)}</div>`}
function bindRecording(){$('#record-start').onclick=()=>{try{const s=getScene($('#record-scene').value);state.draft={sceneId:s.id,url:assertLocalUrl($('#record-url').value),revision:s.revision+1,code:scriptSample(s,'automation'),validated:false};save();render()}catch(e){toast(e.message)}};if(!state.draft)return;$('#draft-code').oninput=()=>{$('#draft-publish').disabled=true};$('#draft-save').onclick=()=>{state.draft.code=$('#draft-code').value;state.draft.validated=false;save();render();toast('候選版本已修改；需重新驗證')};$('#draft-validate').onclick=()=>{const code=$('#draft-code').value;state.draft.code=code;state.draft.validated=['def automate','params','page.'].every(t=>code.includes(t));save();render();toast(state.draft.validated?'示範契約檢查通過':'缺少 automate、params 或頁面觀察')};$('#draft-publish').onclick=()=>{if(!state.draft.validated||state.draft.code!==$('#draft-code').value)return toast('內容已修改，請重新驗證');const s=getScene(state.draft.sceneId);s.revision=state.draft.revision;s.state='已發布';s.url=state.draft.url;s.code=state.draft.code;state.draft=null;save();render();toast('已發布原型候選版本；正式環境須真實執行驗證')}}
function flowBody(){return `<div class="notice">離線模式只演示順序編排與出參傳遞。真實最小鏈路由 python-demo/run_demo.py 執行。</div><div class="flow-layout"><section class="panel panel-body"><h2>場景庫</h2>${state.scenes.filter(s=>s.state==='已發布').map(s=>`<button class="library-item" data-add="${s.id}"><strong>${s.id}</strong><span>${esc(s.name)}</span><small>＋ 加入序列</small></button>`).join('')}</section><section class="panel flow-board"><div class="flow-stage">${state.flow.map((id,i)=>`<div class="flow-node ${i===selectedNode?'selected':''}"><button class="text-btn" data-node="${i}">節點 ${i+1} · ${id}</button><strong>${esc(getScene(id)?.name||'未知場景')}</strong><span class="muted">${id==='BA-002'?'recordId ← 前一節點.output.recordId':'入參 ← 場景預設值'}</span></div>${i<state.flow.length-1?'<div class="flow-arrow" aria-label="接續">↓</div>':''}`).join('')||'<div class="empty">從場景庫加入節點。</div>'}</div></section><section class="panel panel-body"><h2>節點設定</h2><p>選取節點 ${selectedNode+1}</p><div class="actions"><button class="button" id="node-up">上移</button><button class="button" id="node-down">下移</button><button class="button danger" id="node-remove">移除</button></div><hr><label>失敗演示<select id="flow-fail"><option value="-1">全部通過</option>${state.flow.map((id,i)=>`<option value="${i}">節點 ${i+1} 斷言失敗</option>`).join('')}</select></label><p class="muted">依序執行；失敗即停止。沒有有效前置出參時，在執行前攔截。</p><button class="button primary" id="flow-run">模擬執行序列</button><button class="button" id="flow-export">匯出編排 JSON</button><div id="flow-result" role="status"></div></section></div>`}
function bindFlow(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{state.flow.push(b.dataset.add);selectedNode=state.flow.length-1;save();render()});document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{selectedNode=+b.dataset.node;render()});for(const [id,delta]of [['node-up',-1],['node-down',1]])$('#'+id).onclick=()=>{const next=selectedNode+delta;if(next<0||next>=state.flow.length)return;[state.flow[next],state.flow[selectedNode]]=[state.flow[selectedNode],state.flow[next]];selectedNode=next;save();render()};$('#node-remove').onclick=()=>{state.flow.splice(selectedNode,1);selectedNode=Math.max(0,Math.min(selectedNode,state.flow.length-1));save();render()};$('#flow-export').onclick=()=>download('workflow.json',json({version:1,mode:'serial',onFailure:'stop',nodes:state.flow.map((id,i)=>({nodeId:'node-'+(i+1),sceneId:id,revision:getScene(id).revision,inputs:id==='BA-002'?{recordId:'${node-'+i+'.output.recordId}'}:getScene(id).defaults}))}));$('#flow-run').onclick=()=>{try{if(!state.flow.length)throw Error('請先加入節點');state.flow.forEach((id,i)=>{const s=getScene(id);if(!s||s.state!=='已發布')throw Error('節點 '+(i+1)+' 尚未發布');if(id==='BA-002'&&(i===0||!['BA-001','BA-002'].includes(state.flow[i-1])))throw Error('節點 '+(i+1)+' 缺少前置 recordId');if(id!=='BA-002')validate(s.defaults,s.inputSchema)});let previous=null,lines=[];for(let i=0;i<state.flow.length;i++){const s=getScene(state.flow[i]),input=s.id==='BA-002'?{recordId:previous.recordId}:clone(s.defaults);const r=simulate(s,input,+$('#flow-fail').value===i);lines.push(`節點 ${i+1} ${s.id}：${r.status==='passed'?'通過':'失敗，後續停止'}`);if(r.status!=='passed')break;if(s.id==='BA-002'){r.output={...previous};save()}previous=r.output}$('#flow-result').innerHTML='<pre class="source">'+esc(lines.join('\n'))+'</pre><a href="#reports">查看報告</a>'}catch(e){$('#flow-result').textContent=e.message}}}
const architecture=`<div class="stack"><div class="notice">這是一個通用瀏覽器自動化 MVP。場景名稱、頁面與資料均為中性示範，不包含原工程的任何業務規則。</div>${panel('最小系統結構',`<div class="panel-body"><div class="four-col">${[['Portal 介面','場景卡片／錄製／報告／試驗場'],['Flask API','場景、版本、入參、執行與工作階段'],['執行 Worker','Playwright 自動化 → 獨立斷言 → 出參'],['資料與產物','SQLite 元資料；檔案目錄存放腳本與報告']].map(x=>`<div class="notice"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div><p class="muted">請求方向：Portal → API → Worker。Worker 寫入執行狀態及產物，Portal 透過輪詢／事件串流讀取進度。長任務不可阻塞 Web 請求。</p></div>`)}${panel('分工與可驗收產出',`<div class="table-scroll"><table><thead><tr><th>模組</th><th>責任</th><th>交付介面</th><th>驗收證據</th></tr></thead><tbody><tr><td>Portal / 介面</td><td>共同外殼、卡片、表單、篩選、編排與狀態</td><td>共用 CSS、路由、API 客戶端</td><td>桌面及窄屏檢查、鍵盤操作</td></tr><tr><td>場景與版本</td><td>穩定 ID、不可變版本、Schema 與發布門檻</td><td>Scene / Revision / Run 契約</td><td>修改後舊驗證結果不可再次發布</td></tr><tr><td>瀏覽器執行</td><td>隔離 Context、腳本、斷言、總期限、取消</td><td>參數檔 → facts.json → output.json</td><td>成功、失敗、超時；Context 清理</td></tr><tr><td>場景生產</td><td>原始錄製、助手上下文、受控工具、候選驗證</td><td>Recording / DebugSession / Revision</td><td>助手只改草稿；使用者確認發布</td></tr><tr><td>報告與編排</td><td>步驟證據、出參綁定、失敗停止、歷史快照</td><td>Report / Workflow / NodeRun</td><td>上游成功才向下游發布出參</td></tr></tbody></table></div>`)}${panel('建置順序與範圍',`<div class="panel-body prose"><ol><li><strong>先打通一條真實鏈路：</strong>本包 Python 範例的兩個場景。可實際產生入參、頁面截圖、斷言、出參與 HTML 報告。</li><li><strong>接上管理頁：</strong>將原型 localStorage 換成 Flask API + SQLite；執行端使用背景 Worker。先採單機、單使用者、序列執行。</li><li><strong>接上錄製與助手：</strong>保留 Playwright 原稿，助手轉成候選標準腳本；經真實執行與斷言通過後由使用者發布。</li><li><strong>接上自由試驗場：</strong>先支持序列、前置出參引用、失敗停止與可見的參數解析結果。</li></ol><p>本輪 MVP 不要求任意 DAG、分散式叢集、多租戶權限或跨環境排程。新工程若增加這些能力，應另行定義需求。</p></div>`)}</div>`;
const contracts=`<div class="stack">${panel('檔案與執行契約',`<div class="panel-body prose"><pre class="source">scenes/BA-001/revisions/0001/
  automation.py       # 接受 --input --facts --screenshot --target-url
  assertion.py        # 接受 --input --facts --output
  input.schema.json   # 必填、型別與範圍
  defaults.json
  output.schema.json
  example.json
runs/&lt;run-id&gt;/
  input.json          # 已解析及驗證的本次參數快照
  facts.json          # 瀏覽器實際觀察；不是直接宣稱成功
  output.json         # 自動化、獨立斷言與出參 Schema 全通過後才發布
  screenshot.png
  automation.log / assertion.log
  script-snapshot/    # 本次程式版本
  result.json / report.html</pre><p>執行時把參數檔路徑傳入 Python。使用資料讀取取代字串替換與 eval。憑證只能傳識別碼，不能放在入參、上下文、報告或版本庫中。</p><div class="field-pair"><div><h3>BA-001 入參</h3><pre class="source">${esc(json(seeds[0].defaults))}</pre></div><div><h3>成功出參</h3><pre class="source">${esc(json(seeds[0].example))}</pre></div></div><p>BA-002 入參為 recordId，出參與 BA-001 相同。Schema 採 JSON Schema 2020-12，正式後端完整驗證，本離線原型只覆蓋示範所需的基本規則。</p></div>`)}${panel('資料模型與 API 提案（新工程待實作）',`<div class="panel-body prose"><p><strong>Scene：</strong>id、name、group、defaultDebugUrl、publishedRevision。<strong>Revision：</strong>sceneId、version、腳本雜湊、Schema、defaults、status。<strong>Run：</strong>runId、sceneId、revision、status、deadline、input、output、artifacts、error。<strong>DebugSession：</strong>sessionId、sceneId、revision、browserContextId、expiresAt。<strong>Workflow：</strong>version、nodes、inputBindings。</p><div class="table-scroll"><table><thead><tr><th>介面</th><th>用途</th><th>約束</th></tr></thead><tbody><tr><td>GET /api/scenes</td><td>場景清單</td><td>篩選、分頁；ID 永久穩定</td></tr><tr><td>POST /api/scenes/{id}/revisions</td><td>儲存候選版本</td><td>baseRevision 不符回 409</td></tr><tr><td>POST /api/scenes/{id}/runs</td><td>驗參並排入執行</td><td>revision + input + idempotencyKey；202 回 runId</td></tr><tr><td>GET /api/runs/{runId}</td><td>狀態與產物位置</td><td>不暴露絕對路徑與憑證</td></tr><tr><td>POST /api/runs/{runId}/cancel</td><td>請求取消</td><td>中止 Worker／瀏覽器；不回滾外部動作</td></tr><tr><td>POST /api/debug-sessions</td><td>隔離瀏覽器與助手</td><td>sceneId、revision、targetUrl、credentialRef</td></tr><tr><td>POST /api/revisions/{id}/publish</td><td>發布通過驗證的版本</td><td>核對腳本雜湊與成功 Run；使用者確認</td></tr><tr><td>POST /api/workflows/{id}/runs</td><td>執行編排</td><td>固定版本、檢查出參引用與節點順序</td></tr></tbody></table></div></div>`)}${panel('狀態、期限與隔離',`<div class="panel-body prose"><p><strong>版本：</strong>草稿 → 驗證中 → 通過／失敗 → 已發布。修改腳本、Schema 或預設參數後，必須使舊驗證失效。</p><p><strong>執行：</strong>queued → running → passed / failed / timed_out / cancelled。執行失敗不自動重複點擊有副作用的按鈕。</p><p><strong>總期限：</strong>使用單調時鐘。每次等待只能消耗剩餘時間；Worker 外層另設硬期限，超時終止程序群組。登入檢查節流，不在每次輪詢掃描所有頁面。</p><p><strong>隔離：</strong>每次執行及每個角色使用獨立 BrowserContext。登入失效回報 needs_login，引導使用者手動登入並保存隔離憑證，再續跑可恢復步驟。不得混用不同角色的 storageState。</p><p><strong>助手工具：</strong>讀取本場景檔案、觀察本工作階段、編輯草稿、執行候選版、查看本次證據。禁止任意主機 Shell、讀取其他工作階段或自動發布。預設網址需要驗證，部署時限制可訪問網域與內網位址。</p><p><strong>診斷：</strong>記錄階段、剩餘秒數、網址、定位器、目前 DOM 狀態、錯誤類型；失敗盡力截圖，截圖不可拖過總期限。必要時保留 trace；敏感頁面需遮罩或限制存取。</p></div>`)}</div>`;
const startGuide=`<div class="stack">${panel('本包實際提供什麼',`<div class="table-scroll"><table><thead><tr><th>層次</th><th>已提供</th><th>限制</th></tr></thead><tbody><tr><td>離線 HTML</td><td>兩級 Portal、場景卡片、參數設定、草稿生命週期、報告篩選、序列試驗場</td><td>localStorage 與模擬結果；不連線 AI 或瀏覽器</td></tr><tr><td>Python 真實範例</td><td>本機頁面、自動化、獨立斷言、Schema、入出參、截圖、HTML 報告、兩步串聯、總期限</td><td>命令列執行；本機測試資料，不含登入流程</td></tr><tr><td>新工程實作指引</td><td>資料／API 契約、責任分工、發布門檻與驗收清單</td><td>Flask 管理 API、AI 助手、憑證管理與可視瀏覽器串流需新工程實作</td></tr></tbody></table></div>`)}${panel('真實瀏覽器範例 · 安裝與執行',`<div class="panel-body prose"><p><a class="button primary" href="sample-run/index.html">查看已驗證的真實範例報告</a></p><p>進入壓縮包內 <code>python-demo</code>，使用 Python 3.10+。安裝需連線網路下載套件及 Firefox。</p><pre class="source">python3 -m venv .venv
source .venv/bin/activate
python -m pip install -r requirements.txt
python -m playwright install firefox
python run_demo.py
# 要看見瀏覽器視窗：
python run_demo.py --headed</pre><p>Windows 啟用虛擬環境改用 <code>.venv\\Scripts\\activate</code>。範例的程序群組清理已在 macOS 驗證；Windows 分支附帶 taskkill，仍需團隊驗收。</p><p>完成後開啟命令列顯示的 <code>artifacts/&lt;session-id&gt;/index.html</code>，可查看兩次真實瀏覽器執行的報告與截圖。範例自動開啟本機目標頁服務、執行兩個場景，再釋放瀏覽器。</p><pre class="source"># 自訂 BA-001 入參：
python run_demo.py --input examples/input.json
# 真實錄製另開兩個終端：
python target/server.py --port 8765
python -m playwright codegen --browser firefox --target python -o draft.py http://127.0.0.1:8765/</pre><p>錄製輸出是原稿。按照 scenes/automation.py 與 scenes/assertion.py 拆分動作與斷言、提取入參、補齊出參，再執行驗證。原稿不可直接當成已發布腳本。</p></div>`)}${panel('交給新工程的任務書',`<div class="panel-body prose"><pre class="source">請先完整閱讀本 HTML 的「系統與分工」「資料與介面契約」「執行與驗收」，並執行附帶 Python 範例。使用 Python Flask + Jinja + Playwright 建立通用瀏覽器自動化 MVP。沿用附帶的頂部第一級／左側第二級 Portal 與緊湊樣式，所有文字使用繁體中文。以 BA-001、BA-002 中性範例驗收；不可引入原工程業務。

先落地場景／版本管理、參數 Schema、獨立執行 Worker 與報告，再建置原始錄製 → 助手調試 → 真實驗證 → 人工發布。最後接上序列試驗場。不要把 HTML 模擬結果誤接為真實成功。每一階段提供可重現的驗收命令與證據。</pre><h3>功能驗收清單</h3><ul class="checklist"><li>場景編號不可重用；調試網址可保存及預填。</li><li>缺參、型別錯誤、未知參數在啟動瀏覽器前攔截。</li><li>成功：自動化 + 獨立斷言 + 出參 Schema 全通過；產生 output.json。</li><li>失敗：無成功出參；報告保留階段、錯誤與可取得的截圖。</li><li>超時：整體期限生效，關閉子程序與瀏覽器。</li><li>相同副作用操作不因超時自動重試。</li><li>兩個角色隔離；登入失效可引導人工重新登入。</li><li>助手修改後必須重新驗證；驗證版本必須等於發布版本。</li><li>報告依分類、場景多選篩選，重載頁面仍可查閱歷史。</li><li>編排下游只收到上游成功出參，前置失敗立即停止。</li><li>新工程不依賴本交付者的檔案路徑、帳號或服務。</li></ul><h3>恢復原型</h3><button class="button" id="reset-demo">重設離線示範資料</button><p class="muted">只清除本 HTML 原型的資料，與 Python 產物無關。file:// 下的儲存依瀏覽器而異；跨瀏覽器不共用。</p></div>`)}</div>`;
function render(){const route=shell(config);let html='';
if(route==='scenarios'){$('#page-actions').innerHTML='<a class="button" href="#start">真實範例</a><button class="button primary" id="new-scene">新增場景</button>';html=`<div class="stack"><div class="notice">此處是離線互動原型，所有執行結果都標記為「模擬」。真實 Python／Playwright 範例附於壓縮包。</div><div class="four-col">${[['場景數',state.scenes.length],['已發布',state.scenes.filter(s=>s.state==='已發布').length],['模擬執行',state.reports.length],['成功次數',state.reports.filter(r=>r.status==='passed').length]].map(x=>`<div class="panel panel-body stat"><span class="muted">${x[0]}</span><div class="value">${x[1]}</div></div>`).join('')}</div><div class="toolbar panel"><label class="grow">搜尋 <input type="search" id="search" placeholder="場景編號 / 名稱"></label><label>分類 <select id="scene-group"><option value="">全部分類</option>${[...new Set(state.scenes.map(s=>s.group))].map(g=>`<option>${esc(g)}</option>`).join('')}</select></label></div><div id="cards" class="grid"></div></div>`}
else if(route==='recording')html=recordingBody();
else if(route==='reports')html=`<div class="stack"><div class="notice">多選操作：Windows 按 Ctrl、macOS 按 ⌘ 選取；未選取表示全部。這裡只顯示原型的模擬報告。</div>${panel('執行紀錄',`<div class="toolbar"><label>分類（多選）<select multiple size="2" id="report-groups">${[...new Set(state.scenes.map(s=>s.group))].map(g=>`<option>${esc(g)}</option>`).join('')}</select></label><label class="grow">場景（多選）<select multiple size="3" id="report-scenes">${state.scenes.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.name)}</option>`).join('')}</select></label><label>結果<select id="report-status"><option value="">全部</option><option value="passed">通過</option><option value="failed">失敗</option></select></label><button class="button" id="clear-filters">清除篩選</button></div><div id="report-table"></div>`)}</div>`;
else if(route==='playground')html=flowBody();else if(route==='architecture')html=architecture;else if(route==='contracts')html=contracts;else html=startGuide;
$('#content').innerHTML=html;
if(route==='scenarios'){sceneCards();$('#search').oninput=sceneCards;$('#scene-group').onchange=sceneCards;$('#new-scene').onclick=()=>modal('新增場景',`<div class="notice">建立基於 BA-001 契約的中性草稿；新工程可擴展為自訂腳本。</div><label>場景名稱<input id="scene-name" maxlength="60"></label><label>分類<input id="scene-class" value="範例資料" maxlength="30"></label>`,{label:'建立草稿',run:()=>{const name=$('#scene-name').value.trim(),group=$('#scene-class').value.trim();if(!name||!group)return toast('請填寫名稱與分類');const n=Math.max(...state.scenes.map(s=>+s.id.slice(3)))+1;state.scenes.push({...clone(seeds[0]),id:'BA-'+String(n).padStart(3,'0'),name,group,state:'草稿',revision:1});save();$('#dialog').close();render()}})}
if(route==='recording')bindRecording();if(route==='reports'){reportRows();for(const id of ['report-groups','report-scenes','report-status'])$('#'+id).onchange=reportRows;$('#clear-filters').onclick=()=>{for(const id of ['report-groups','report-scenes'])[...$('#'+id).options].forEach(o=>o.selected=false);$('#report-status').value='';reportRows()}}
if(route==='playground')bindFlow();if(route==='start')$('#reset-demo').onclick=()=>modal('重設離線示範資料','<p>將刪除本原型的場景修改、草稿、編排與模擬報告。</p>',{label:'確認重設',run:()=>{state={scenes:clone(seeds),reports:[],flow:['BA-001','BA-002'],draft:null};selectedNode=0;save();$('#dialog').close();location.hash='scenarios'}})
}
window.addEventListener('hashchange',render);render();
